// «Пройти тест» в кабинете — по карточке на каждый код в test_access пользователя,
// ведущей прямо в ту же модалку направления, что открывается из каталога на главной
// (предметы + «Пройти тест по направлению» / «Симуляция КТ»), без похода в каталог
// вручную. Код доступа может быть кодом ГОП-группы напрямую (M123) или кодом
// контента, отображаемым на ГОП через CONTENT_TO_GOP (7M01 → M001), либо кодом
// направления из старого каталога DIRECTIONS. Без выданного доступа — одна
// карточка-приглашение в общий каталог, как раньше.
// Направление-носитель для общих тестов (английский/ТГО берутся из общих банков, код нужен только серверу).
const COMMON_TEST_CODE = '7M01';

function renderTestAccessCards() {
  const wrap = document.getElementById('testCtaSection');
  if (!wrap) return; // раздел есть только на cabinet.html
  const user = API.getCurrentUser();
  const access = (user && user.access) || [];

  const cards = access.map(code => {
    const gopCode = CONTENT_TO_GOP[code] || (code === 'M019E' ? 'M019' : code);
    const g = KT_STATS_GROUPS.find(x => x.code === gopCode);
    if (g && (code === 'M019' || code === 'M019E')) {
      const en = code === 'M019E';
      return { href: `index.html?openGop=M019&variant=${code}`, code: g.code, name: `${g.name} (${en ? 'английский' : 'французский'} язык)` };
    }
    if (g) return { href: `index.html?openGop=${encodeURIComponent(gopCode)}`, code: g.code, name: g.name };
    const d = DIRECTIONS.find(x => x.code === code);
    if (d) return { href: `index.html?openDir=${encodeURIComponent(code)}`, code: d.code, name: d.name };
    return null;
  }).filter(Boolean);

  if (!cards.length) {
    wrap.innerHTML = `
      <a class="test-cta-card" href="index.html?commonPick=1">
        <div class="test-cta-text">
          <p class="test-cta-eyebrow">${I18N.t('testCta.eyebrow')}</p>
          <h3>${I18N.t('testCta.title')}</h3>
          <p>${I18N.t('testCta.emptyText')}</p>
        </div>
        <span class="test-cta-arrow" aria-hidden="true">→</span>
      </a>
    `;
    return;
  }

  wrap.innerHTML = cards.map(c => `
    <a class="test-cta-card" href="${c.href}">
      <div class="test-cta-text">
        <p class="test-cta-eyebrow">${esc(c.code)} · ${I18N.t('testCta.eyebrow')}</p>
        <h3>${I18N.t('testCta.title')} — ${esc(c.name)}</h3>
        <p>${I18N.t('testCta.text')}</p>
      </div>
      <span class="test-cta-arrow" aria-hidden="true">→</span>
    </a>
  `).join('');
}

// Рендерит раздел «Конспекты» в кабинете. Карточки двух видов:
// — общие предметы (COMMON_CONSPECTS) — видны любому вошедшему пользователю;
// — профильные предметы направления (LIBRARY_CONSPECTS) — по коду в test_access.
// Каждый предмет — своя отдельная карточка (ТГО и английский не объединяются
// друг с другом и не зависят от доступа к конкретному направлению).
// Деление на подразделы (Педагогика / Психология, Критическое / Аналитическое
// мышление и т.д.) происходит уже внутри konspekty.html через переключатель.
// Есть ли у пользователя английский как общий иностранный язык: нет у тех, чьи направления сдают французский
// (FRENCH_LANG_CODES) или только два профильных предмета (PROFILE_ONLY_CODES); без выданного доступа — есть.
function userHasEnglish(access) {
  return access.length === 0 || access.some(c => !FRENCH_LANG_CODES.has(c) && !PROFILE_ONLY_CODES.has(c));
}

function renderConspectsLibrary() {
  const wrap = document.getElementById('konspektySection');
  if (!wrap) return; // раздел есть только на cabinet.html
  const user = API.getCurrentUser();
  // Карточка «Практика · Английский» — только там, где есть английский.
  const practice = document.getElementById('practiceCard');
  if (practice) practice.classList.toggle('hidden', !user || !userHasEnglish(user.access || []));
  if (!user) { wrap.classList.add('hidden'); return; }
  const access = user.access || [];
  // Общие конспекты (ТГО, английский) не показываем тем, у кого доступ только к
  // направлениям без общих предметов (PROFILE_ONLY_CODES, например M078).
  const profileOnlyUser = access.length > 0 && access.every(c => PROFILE_ONLY_CODES.has(c));
  // Французский (общий иностранный язык M019) заменяет английский: тем, у кого доступ только к таким направлениям,
  // английский не показываем, французский — показываем только им (и тем, у кого есть и такие, и обычные направления).
  const hasFrench = access.some(c => FRENCH_LANG_CODES.has(c));
  const hasEnglish = userHasEnglish(access);
  const common = profileOnlyUser ? [] : Object.entries(COMMON_CONSPECTS)
    .filter(([code]) => code === 'french' ? hasFrench : code === 'english' ? hasEnglish : true)
    .map(([code, lib]) => ({ code, lib }));
  const gated = access.map(code => ({ code, lib: LIBRARY_CONSPECTS[code] })).filter(x => x.lib);
  const available = [...common, ...gated];
  if (!available.length) { wrap.classList.add('hidden'); return; }
  wrap.classList.remove('hidden');
  wrap.innerHTML = available.map(({ code, lib }) => {
    const totalTopics = lib.sections.reduce((n, s) => n + s.topics.length, 0);
    const sectionNames = lib.sections.map(s => s.title).join(' · ');
    return `
      <a class="dash-card konspekty-card" href="konspekty.html?code=${encodeURIComponent(code)}">
        <h3>${I18N.t('konspekty.cardPrefix')} ${esc(lib.title)}</h3>
        <p>${sectionNames} — ${totalTopics} ${I18N.t('konspekty.topicsWord')}</p>
        <span class="konspekty-card-arrow" aria-hidden="true">→</span>
      </a>
    `;
  }).join('');
}

const INTERACTIVE_TEST_CODES = ["7M01","7M02","7M03","7M04","7M05","7M06","7M07","7M08","7M11","7M12","M123","M066","M107","M005","M103","M115","M149","M063","M078","M020","M150","M019","M019E"]; // какие направления имеют интерактивный тест (не секрет — просто UI-подсказка, доступ проверяется на бэкенде)

