function categoryOf(code) {
  const n = parseInt(code.slice(1), 10);
  const cat = CATALOG_CATEGORIES.find(c => c.ranges.some(([a, b]) => n >= a && n <= b));
  return cat ? cat.id : 'other';
}

function groupMatchesSearch(g) {
  if (!statsSearch) return true;
  const q = statsSearch.toLowerCase();
  return g.code.toLowerCase().includes(q) || g.name.toLowerCase().includes(q);
}

function sortStatsGroups(list) {
  const arr = [...list];
  if (statsSortKey === 'passed') arr.sort((a, b) => b.passed_pct - a.passed_pct);
  else if (statsSortKey === 'participants') arr.sort((a, b) => b.participants - a.participants);
  else arr.sort((a, b) => a.name.localeCompare(b.name, 'ru'));
  return arr;
}

function pluralizeGroups(n) {
  if (window.I18N && I18N.getLang() === 'kk') return I18N.t('word.group.kk');
  const mod10 = n % 10, mod100 = n % 100;
  if (mod10 === 1 && mod100 !== 11) return 'группа';
  if ([2, 3, 4].includes(mod10) && ![12, 13, 14].includes(mod100)) return 'группы';
  return 'групп';
}

// SVG-кольцо-индикатор (замена прогресс-барам) — pct 0-100, size/stroke в px,
// цвет по умолчанию — семантика сдал/не сдал (>=50 — teal, иначе danger).
function ringSvg(pct, { size = 64, stroke = 6, color, numFontSize } = {}) {
  const r = (size - stroke) / 2;
  const c = 2 * Math.PI * r;
  const offset = c * (1 - Math.max(0, Math.min(100, pct)) / 100);
  const ringColor = color || (pct >= 50 ? 'var(--teal)' : 'var(--danger)');
  const fs = numFontSize || Math.round(size * 0.22);
  return `
    <div class="ring-wrap" style="width:${size}px;height:${size}px;">
      <svg viewBox="0 0 ${size} ${size}">
        <circle class="ring-track" cx="${size / 2}" cy="${size / 2}" r="${r}" stroke-width="${stroke}"></circle>
        <circle class="ring-fill" cx="${size / 2}" cy="${size / 2}" r="${r}" stroke-width="${stroke}"
                stroke-dasharray="${c}" stroke-dashoffset="${offset}" style="stroke:${ringColor}"></circle>
      </svg>
      <div class="ring-num" style="font-size:${fs}px;">${Math.round(pct)}%</div>
    </div>
  `;
}

// Считает число от 0 до target за duration мс (ease-out), опционально с суффиксом (напр. "%").
function countUp(el, target, { duration = 1200, suffix = '' } = {}) {
  if (window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
    el.textContent = target + suffix;
    return;
  }
  const start = performance.now();
  function tick(now) {
    const p = Math.min(1, (now - start) / duration);
    const eased = 1 - Math.pow(1 - p, 3);
    el.textContent = Math.round(target * eased) + suffix;
    if (p < 1) requestAnimationFrame(tick);
  }
  requestAnimationFrame(tick);
  // Страховка: если вкладка в это время была свёрнута/неактивна, requestAnimationFrame
  // не тикает и счётчик застревает на 0 — принудительно выставляем верное значение.
  setTimeout(() => { el.textContent = target + suffix; }, duration + 150);
}

// Лёгкая вспышка конфетти из центра контейнера (для успешного результата теста) —
// без внешних библиотек, цвета берутся из палитры сайта. Уважает prefers-reduced-motion.
const CONFETTI_COLORS = ['var(--accent)', 'var(--beige)', 'var(--teal)'];
function burstConfetti(container, count = 18) {
  if (!container) return;
  if (window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;
  for (let i = 0; i < count; i++) {
    const piece = document.createElement('span');
    piece.className = 'confetti-piece';
    const angle = Math.random() * Math.PI * 2;
    const dist = 70 + Math.random() * 60;
    piece.style.setProperty('--cx', Math.cos(angle) * dist + 'px');
    piece.style.setProperty('--cy', Math.sin(angle) * dist + 'px');
    piece.style.setProperty('--cr', (Math.random() * 360 - 180) + 'deg');
    piece.style.background = CONFETTI_COLORS[i % CONFETTI_COLORS.length];
    piece.style.animationDelay = Math.round(Math.random() * 120) + 'ms';
    piece.addEventListener('animationend', () => piece.remove());
    container.appendChild(piece);
  }
}

function renderCategoryTiles() {
  const wrap = document.getElementById('catTiles');
  if (!wrap) return;
  const counts = {};
  KT_STATS_GROUPS.forEach(g => { const c = categoryOf(g.code); counts[c] = (counts[c] || 0) + 1; });
  wrap.innerHTML = `
    <button class="kcat-tile ${activeCategory === null ? 'is-active' : ''}" data-cat="">
      <span class="kcat-tile-icon">${CAT_ICONS.all}</span>
      <span class="kcat-tile-label">${I18N.t('catalog.allGroups')}</span>
      <span class="kcat-tile-count">${KT_STATS_GROUPS.length}</span>
    </button>
    ${CATALOG_CATEGORIES.map(c => `
    <button class="kcat-tile ${activeCategory === c.id ? 'is-active' : ''}" data-cat="${c.id}">
      <span class="kcat-tile-icon">${CAT_ICONS[c.icon]}</span>
      <span class="kcat-tile-label">${c.label}</span>
      <span class="kcat-tile-count">${counts[c.id] || 0}</span>
    </button>`).join('')}
  `;
  wrap.querySelectorAll('[data-cat]').forEach(btn => btn.addEventListener('click', () => {
    activeCategory = btn.dataset.cat || null;
    renderStatsCatalog();
  }));
}

function renderStatsCatalog() {
  const listEl = document.getElementById('statsList');
  if (!listEl) return; // новый каталог только на index.html
  const empty = document.getElementById('statsEmpty');
  const count = document.getElementById('statsCount');

  renderCategoryTiles();

  let matched = KT_STATS_GROUPS.filter(groupMatchesSearch);
  if (activeCategory) matched = matched.filter(g => categoryOf(g.code) === activeCategory);
  matched = sortStatsGroups(matched);

  listEl.innerHTML = matched.map(g => `
    <button class="card" data-code="${g.code}">
      ${ringSvg(g.passed_pct)}
      <div class="card-body">
        <div class="code">${g.code}</div>
        <h3>${esc(g.name)}</h3>
        <div class="card-foot">${I18N.t('catalog.applications')} <b>${g.applications}</b></div>
      </div>
    </button>
  `).join('');
  empty.classList.toggle('hidden', matched.length > 0);
  count.textContent = `${matched.length} ${pluralizeGroups(matched.length)}`;

  listEl.querySelectorAll('[data-code]').forEach(btn => btn.addEventListener('click', () => openGopGroup(btn.dataset.code)));
}

