/* ---------------------------------------------------------
   5) КВИЗ-ДВИЖОК (тест по направлению)
   --------------------------------------------------------- */
// kt.js — интерфейс симуляции КТ и названия предметов. Банков вопросов в нём больше
// нет (они на сервере), поэтому файл небольшой, но каталог, карточки направлений и
// кабинет по-прежнему обходятся без него: грузим только в момент первого реального
// запуска теста/симуляции (клик, а не заход на страницу).
let ktJsPromise = null;
function loadKtJs() {
  if (typeof window.openKT === 'function') return Promise.resolve();
  if (!ktJsPromise) {
    ktJsPromise = new Promise((resolve, reject) => {
      const s = document.createElement('script');
      s.src = 'kt.min.js?v=20';
      s.onload = resolve;
      s.onerror = () => { ktJsPromise = null; reject(new Error('Не удалось загрузить тест — проверьте соединение')); };
      document.body.appendChild(s);
    });
  }
  return ktJsPromise;
}
async function openKTSafe(code) {
  try { await loadKtJs(); } catch (e) { showToast(e.message); return; }
  window.openKT(code);
}

async function startQuiz(code) {
  try { await loadKtJs(); } catch (e) { showToast(e.message); return; }
  showSubjectPicker(code);
}

// Экран выбора предмета — только для простого теста (не для симуляции КТ, та
// специально всегда комбинированная, как настоящий экзамен). Всегда 4 секции,
// как на настоящем КТ: 2 общих (Английский, ТГО) + 2 профильных. Общие секции
// не требуют выданного доступа (как и в симуляции КТ) — только вход в аккаунт;
// доступ проверяется отдельно, только при выборе профильного предмета.
function showSubjectPicker(code, commonOnly) {
  const d = commonOnly ? null : findDirection(code);
  const profileOnly = PROFILE_ONLY_CODES.has(code);
  const subj = (typeof KT_SUBJECT_NAMES !== 'undefined' && KT_SUBJECT_NAMES[code])
    || { subj1: 'Профильный предмет №1', subj2: 'Профильный предмет №2' };
  const body = document.getElementById('subjectModalBody');
  body.innerHTML = `
    <p class="eyebrow">${d ? d.code + ' · ' : ''}Пройти тест</p>
    <h3 class="modal-title">Выберите предмет</h3>
    <p class="modal-lead">${commonOnly ? 'Английский и ТГО доступны сразу после регистрации.' : profileOnly ? 'Тест состоит из 2 профильных предметов — потренируйтесь по каждому отдельно.' : 'Тест состоит из 4 предметов, как на настоящем КТ — потренируйтесь по каждому отдельно.'}</p>
    <div class="kt-type-cards">
      ${profileOnly ? '' : `<button class="kt-type-card" data-subject="lang"><span class="kt-type-name">${FRENCH_LANG_CODES.has(code) ? 'Французский' : 'Английский'}</span></button>
      <button class="kt-type-card" data-subject="logic"><span class="kt-type-name">ТГО</span></button>`}
      ${commonOnly ? '' : `<button class="kt-type-card" data-subject="subj1"><span class="kt-type-name">${subj.subj1}</span></button>
      <button class="kt-type-card" data-subject="subj2"><span class="kt-type-name">${subj.subj2}</span></button>`}
    </div>
  `;
  body.querySelectorAll('[data-subject]').forEach(btn => btn.addEventListener('click', () => {
    document.getElementById('subjectModal').classList.add('hidden');
    beginQuizSection(code, btn.dataset.subject);
  }));
  document.getElementById('subjectModal').classList.remove('hidden');
}

function wireSubjectModal() {
  const modal = document.getElementById('subjectModal');
  if (!modal) return;
  const close = () => modal.classList.add('hidden');
  document.getElementById('subjectClose').addEventListener('click', close);
  modal.addEventListener('click', (e) => { if (e.target.id === 'subjectModal') close(); });
}

async function beginQuizSection(code, section) {
  const d = findDirection(code);
  // Вариант собирает сервер: пул предмета перемешивается и обрезается до 50 вопросов.
  // Английский и ТГО доступны любому вошедшему пользователю; профильные предметы —
  // только с выданным доступом (иначе сервер ответит 403 и покажется гейт).
  const att = await startAttempt(code, { kind: 'subject', section });
  if (!att) return;
  const names = (typeof KT_SUBJECT_NAMES !== 'undefined' && KT_SUBJECT_NAMES[code]) || null;
  const title = (section === 'subj1' || section === 'subj2') ? ((names && names[section]) || att.title) : att.title;
  activeQuiz = { attemptId: att.id, code, section, qIndex: 0, answers: new Array(att.questions.length).fill(null), pool: att.questions, result: null };

  document.getElementById('testTitle').textContent = title;
  document.getElementById('testSub').textContent = code === COMMON_TEST_CODE && (section === 'lang' || section === 'logic') ? '' : d ? `${d.code} · ${d.name}` : '';
  document.getElementById('testRun').classList.remove('hidden');
  document.getElementById('testResult').classList.add('hidden');
  document.getElementById('dirModal').classList.add('hidden');
  document.getElementById('resultPage')?.classList.add('hidden'); // если открыт со страницы деталей прошлой попытки

  renderQuizQuestion();
  document.getElementById('testPage').classList.remove('hidden');
  document.body.classList.add('test-open');
  window.scrollTo(0, 0);
}

function closeQuiz() {
  document.getElementById('testPage').classList.add('hidden');
  document.body.classList.remove('test-open');
  activeQuiz = null;
}

// Текст вопроса теста: экранирование + дробная черта для направлений из KT_FRAC_CODES (kt.js,
// подключён на той же странице index.html, что и тест).
function quizText(text) {
  const html = esc(text);
  return activeQuiz && typeof ktFracEnabled === 'function' && ktFracEnabled(activeQuiz.code, activeQuiz.section) ? ktFracHtml(html) : html;
}

// экранирование HTML — варианты могут содержать <a>, <link> и т.п.
function esc(s) {
  return String(s).replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
}

// Конспект хранится как обычный текст с переносами строк и «• пункт» для
// перечислений — разбираем на абзацы/список, чтобы карточка конспекта в
// разборе теста читалась как оформленная заметка, а не сплошной абзац.
// «## Заголовок» — подраздел (нужно для полнотекстовых конспектов по теме,
// где фактов много и их группируют по смыслу — в конспекте одного вопроса
// заголовки не встречаются).
function formatConspectText(text) {
  // **термин** — акцентный жирный; {{g|r|o|p|b:текст}} — цветной акцент (зелёный, красный, оранжевый,
  // фиолетовый, синий); «> …» — заметка; «>+ …» совет, «>! …» ловушка, «>? …» пример; строки «| a | b |» —
  // таблица (если после первой строки идёт «|---|», она — шапка).
  const inl = x => esc(x)
    .replace(/\*\*(.+?)\*\*/g, '<strong class="kp-term">$1</strong>')
    .replace(/\{\{([grobp]):(.+?)\}\}/g, '<span class="kp-c kp-c-$1">$2</span>');
  const blocks = [];
  let list = null, table = null;
  String(text).split('\n').forEach(line => {
    const t = line.trim();
    if (!t) { list = null; table = null; return; }
    if (t.startsWith('|')) {
      list = null;
      if (/^\|[-\s|:]+\|?$/.test(t)) { if (table) table.head = true; return; }
      if (!table) { table = { rows: [], head: false }; blocks.push({ table }); }
      table.rows.push(t.replace(/^\||\|$/g, '').split('|').map(c => c.trim()));
      return;
    }
    table = null;
    if (t.startsWith('## ')) {
      list = null;
      blocks.push({ h: t.slice(3).trim() });
    } else if (/^>[+!?] /.test(t)) {
      list = null;
      blocks.push({ q: t.slice(3).trim(), kind: { '+': 'tip', '!': 'warn', '?': 'ex' }[t[1]] });
    } else if (t.startsWith('> ')) {
      list = null;
      blocks.push({ q: t.slice(2).trim() });
    } else if (t.startsWith('•')) {
      if (!list) { list = []; blocks.push({ list }); }
      list.push(t.slice(1).trim());
    } else {
      list = null;
      blocks.push({ p: t });
    }
  });
  return blocks.map(b => b.h
    ? `<h4 class="rev-conspect-h">${esc(b.h)}</h4>`
    : b.q
    ? `<p class="kp-callout${b.kind ? ' kp-' + b.kind : ''}">${inl(b.q)}</p>`
    : b.table
    ? `<div class="kp-table-wrap"><table class="kp-table">${b.table.rows.map((r, i) => {
        const tag = b.table.head && i === 0 ? 'th' : 'td';
        return `<tr>${r.map(c => `<${tag}>${inl(c)}</${tag}>`).join('')}</tr>`;
      }).join('')}</table></div>`
    : b.list
    ? `<ul class="rev-conspect-list">${b.list.map(i => `<li>${inl(i)}</li>`).join('')}</ul>`
    : `<p>${inl(b.p)}</p>`
  ).join('');
}

// Иконка-книжка перед подписью кнопки «Конспект» в разборе теста.
const REV_CONSPECT_ICON = '<svg class="rev-conspect-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M4 19.5A2.5 2.5 0 0 1 6.5 17H20"/><path d="M6.5 2H20v20H6.5A2.5 2.5 0 0 1 4 19.5v-15A2.5 2.5 0 0 1 6.5 2z"/></svg>';

// Номерная навигация по вопросам (как в симуляции КТ) — клик прыгает на вопрос,
// текущий подсвечен акцентом, отвеченные становятся тёмными.
function renderQuizQnav() {
  const qnav = document.getElementById('testQnav');
  if (!qnav) return;
  qnav.innerHTML = activeQuiz.pool.map((q, i) => {
    const ans = activeQuiz.answers[i];
    const answered = ans != null && (!Array.isArray(ans) || ans.length);
    const cls = i === activeQuiz.qIndex ? 'is-current' : (answered ? 'is-answered' : '');
    return `<button class="kt-qnav-btn ${cls}" data-idx="${i}">${i + 1}</button>`;
  }).join('');
  qnav.querySelectorAll('.kt-qnav-btn').forEach(b => b.addEventListener('click', () => quizGoTo(Number(b.dataset.idx))));
  const curBtn = qnav.querySelector('.kt-qnav-btn.is-current');
  if (curBtn) curBtn.scrollIntoView({ block: 'nearest', inline: 'center' });
}

function quizGoTo(idx) {
  if (idx >= 0 && idx < activeQuiz.pool.length) { activeQuiz.qIndex = idx; renderQuizQuestion(); }
}

function renderQuizQuestion() {
  const q = activeQuiz.pool[activeQuiz.qIndex];
  renderQuizQnav();
  document.getElementById('testQNum').textContent = `${activeQuiz.qIndex + 1}.`;
  document.getElementById('testQuestion').innerHTML = q.imageReplacesText ? '' : quizText(q.q);

  // Аудио (Listening) или текст для чтения (Reading) — только у блока «Английский».
  const mediaEl = document.getElementById('testMedia');
  if (mediaEl) {
    mediaEl.innerHTML = q.audio
      ? `<audio controls preload="none" src="${q.audio}" class="quiz-audio-player"></audio>`
      : (q.passage ? `<div class="kt-reading-passage">${esc(q.passage)}</div>` : '');
  }
  // Картинка к вопросу — есть у части вопросов ТГО (математика).
  const imageEl = document.getElementById('testImage');
  if (imageEl) {
    imageEl.innerHTML = q.image ? `<div class="kt-question-image${q.imageReplacesText ? ' math-question-image' : ''}"><img src="${q.image}" alt="Условие вопроса"></div>` : '';
  }

  const isMulti = !!q.multi; // чекбоксы/радио определяет сервер: ключей на клиенте до сдачи нет
  const curAns = activeQuiz.answers[activeQuiz.qIndex];
  const hintEl = document.getElementById('testMultiHint');
  if (hintEl) hintEl.remove();
  if (isMulti) {
    const hint = document.createElement('p');
    hint.id = 'testMultiHint';
    hint.className = 'kt-multi-hint';
    hint.textContent = 'Выберите все подходящие варианты';
    document.getElementById('testQuestion').insertAdjacentElement('afterend', hint);
  }

  const optionsEl = document.getElementById('testOptions');
  optionsEl.innerHTML = q.options.map((opt, i) => {
    const isSel = isMulti ? (Array.isArray(curAns) && curAns.includes(i)) : curAns === i;
    return `
    <button class="test-opt ${isSel ? 'is-selected' : ''}" data-option="${i}">
      <span class="test-radio ${isMulti ? 'is-checkbox' : ''}" aria-hidden="true"></span>${q.optionImages && q.optionImages[i] ? `<span class="test-opt-image"><img src="${q.optionImages[i]}" alt="Вариант ответа"></span>` : `<span class="test-opt-label">${quizText(opt)}</span>`}
    </button>`;
  }).join('');
  optionsEl.querySelectorAll('[data-option]').forEach(btn => {
    btn.addEventListener('click', () => {
      const i = Number(btn.dataset.option);
      if (q.multi) {
        const cur = Array.isArray(activeQuiz.answers[activeQuiz.qIndex]) ? activeQuiz.answers[activeQuiz.qIndex].slice() : [];
        const pos = cur.indexOf(i);
        if (pos === -1) cur.push(i); else cur.splice(pos, 1);
        activeQuiz.answers[activeQuiz.qIndex] = cur;
      } else {
        activeQuiz.answers[activeQuiz.qIndex] = i;
      }
      renderQuizQuestion();
    });
  });

  document.getElementById('testNext').textContent =
    activeQuiz.qIndex === activeQuiz.pool.length - 1 ? 'Завершить' : 'Далее';
  document.getElementById('testPrev').disabled = activeQuiz.qIndex === 0;
}

function quizPrev() {
  if (activeQuiz.qIndex > 0) { activeQuiz.qIndex--; renderQuizQuestion(); }
}

function quizNext() {
  if (activeQuiz.qIndex < activeQuiz.pool.length - 1) { activeQuiz.qIndex++; renderQuizQuestion(); }
  else finishQuiz();
}

// Верен ли ответ — ТОЛЬКО для подсветки в разборе, когда сервер уже вернул ключи после
// сдачи. Балл и вердикт считает сервер. correct — число или массив; ответ приводим к
// массиву, потому что в предметах с частичным баллом чекбоксы даже у одиночных вопросов.
function quizIsCorrect(q, ua) {
  const correct = Array.isArray(q.correct) ? q.correct : [q.correct];
  const user = Array.isArray(ua) ? ua : (ua == null ? [] : [ua]);
  return user.length > 0 && correct.slice().sort().join(',') === user.slice().sort().join(',');
}

// Тёплое сообщение по итогам теста — хвалит за хороший результат, подбадривает при неудаче.
// Используется и на экране обычного теста по предмету, и на экране полной симуляции КТ.
function quizPraiseMessage(score, total, passed) {
  const pct = total > 0 ? Math.round((score / total) * 100) : 0;
  if (passed && pct >= 90) return 'Отлично! Вы прошли тест — почти без ошибок, так держать.';
  if (passed && pct >= 75) return 'Прекрасный результат! Тест пройден уверенно, молодец.';
  if (passed) return 'Тест пройден. Ещё немного практики — и результат станет ещё увереннее.';
  if (pct >= 40) return 'Пока не хватило до проходного балла, но прогресс виден. Разберите ошибки в «Работе над ошибками» и попробуйте снова.';
  return 'Тест не сдан — но это нормальная часть подготовки. Изучите конспекты по ошибкам и повторите тест, всё получится.';
}

// Сдача теста: ответы уходят на сервер, он сам проверяет их, считает балл и вердикт,
// сохраняет результат и возвращает разбор с ключами. До сдачи в браузере нет ни одного
// ключа ответа. Сдача идемпотентна: при сбое сети ответы остаются на экране, и
// повторное нажатие «Завершить» безопасно.
let quizSubmitting = false;
async function finishQuiz() {
  if (!activeQuiz || quizSubmitting) return;
  const quiz = activeQuiz;
  const nextBtn = document.getElementById('testNext');
  quizSubmitting = true;
  nextBtn.disabled = true;
  nextBtn.textContent = I18N.t('test.checking');
  let r;
  try {
    r = await API.submitAttempt(quiz.attemptId, quiz.answers);
  } catch (e) {
    quizSubmitting = false;
    nextBtn.disabled = false;
    if (e.status === 410 || e.status === 409 || e.status === 404) {
      showToast(I18N.t(e.status === 410 ? 'test.expired' : 'test.stale'));
      closeQuiz();
    } else {
      showToast(e.status ? e.message : I18N.t('test.submitRetry'));
      renderQuizQuestion();
    }
    return;
  }
  quizSubmitting = false;
  if (activeQuiz !== quiz) return; // тест закрыли, пока шла проверка

  quiz.result = r.result;
  // ключи и объяснения приходят только теперь — подмешиваем их для «Работы над ошибками»
  quiz.pool = quiz.pool.map((q, i) => ({ ...q, ...r.review[i] }));
  const { score, total, passed } = r.result;
  const praise = quizPraiseMessage(score, total, passed);
  renderDashboard();

  const stamp = document.getElementById('quizStamp');
  stamp.classList.toggle('is-fail', !passed);
  document.getElementById('stampStatus').textContent = passed ? I18N.t('test.passed') : I18N.t('test.notPassed');
  const stampScoreEl = document.getElementById('stampScore');
  stampScoreEl.textContent = `0/${total}`;
  countUp(stampScoreEl, score, { duration: 900, suffix: `/${total}` });
  document.getElementById('resultHeadline').textContent = passed ? 'Тест пройден' : 'Пока не получилось';
  document.getElementById('resultText').textContent = `${praise} Результат сохранён в кабинете.`;

  document.getElementById('testRun').classList.add('hidden');
  document.getElementById('testResult').classList.remove('hidden');
  nextBtn.disabled = false;
  if (passed) burstConfetti(stamp);
}

// HTML одного вопроса в разборе: варианты с пометками «верно / ваш ответ», объяснения,
// конспект. Общий для «Работы над ошибками» после теста и для страницы деталей результата.
// q — вопрос с ключами (correct, explanations, ...), ua — ответ пользователя (null/число/массив).
function reviewItemHtml(q, ua, i, code) {
  const isMulti = Array.isArray(q.correct);
  const correctSet = isMulti ? q.correct : [q.correct];
  const userSet = Array.isArray(ua) ? ua : (ua == null ? [] : [ua]);
  const wrong = !quizIsCorrect(q, ua);
  const opts = q.options.map((o, oi) => {
    const isCorrectOpt = correctSet.includes(oi);
    const isUserOpt = userSet.includes(oi);
    let cls = 'rev-opt', tag = '';
    if (isCorrectOpt) { cls += ' correct'; tag = isUserOpt ? '<span class="rev-tag ok">Ваш ответ ✓</span>' : '<span class="rev-tag ok">Правильный ответ</span>'; }
    else if (isUserOpt) { cls += ' wrong'; tag = '<span class="rev-tag bad">Ваш ответ ✗</span>'; }
    // Объяснение для студентов по каждому варианту, если есть в данных.
    const expl = q.explanations && q.explanations[oi]
      ? `<div class="rev-opt-expl">${quizText(q.explanations[oi])}</div>` : '';
    const optContent = q.optionImages && q.optionImages[oi]
      ? `<span class="rev-opt-image"><img src="${q.optionImages[oi]}" alt="Вариант ответа"></span>` : `<span>${quizText(o)}</span>`;
    return `<div class="${cls}"><div class="rev-opt-row">${optContent}${tag}</div>${expl}</div>`;
  }).join('');
  const why = q.explanations ? '' : (q.why
    ? `<div class="rev-why"><b>Почему:</b> ${esc(q.why)}</div>`
    : `<div class="rev-why"><b>${correctSet.length > 1 ? 'Правильные ответы' : 'Правильный ответ'}:</b> ${correctSet.map(i => esc(q.options[i])).join('; ')}</div>`);
  // Кнопка «Конспекты» — отдельный подробный разбор вопроса (не привязан к тому,
  // ответил ли пользователь верно), раскрывается по клику, изолирован своей карточкой.
  const conspectBody = q.conspectImage
    ? `<div class="rev-conspect-body"><img class="rev-conspect-image" src="${q.conspectImage}" alt="Конспект"></div>`
    : (q.conspect ? `<div class="rev-conspect-body rev-conspect-text">${formatConspectText(q.conspect)}</div>` : '');
  const conspectBlock = conspectBody
    ? `<details class="rev-conspect-block"><summary class="rev-conspect-btn"><span class="rev-conspect-btn-label">${REV_CONSPECT_ICON}<span>Конспект</span></span></summary>${conspectBody}</details>`
    : '';
  return `
    <div class="rev-item ${wrong ? 'is-wrong' : 'is-ok'}">
      <p class="rev-q"><span class="test-qnum">${i + 1}.</span> ${q.imageReplacesText ? '' : quizText(q.q)}</p>
      ${q.image ? `<div class="kt-question-image${q.imageReplacesText ? ' math-question-image' : ''}"><img src="${q.image}" alt="Условие вопроса"></div>` : ''}
      ${q.passage ? `<div class="kt-reading-passage">${esc(q.passage)}</div>` : ''}
      <div class="rev-opts">${opts}</div>
      ${why}
      ${conspectBlock}
      ${reviewTopicLink(code, q.topic)}
    </div>`;
}

// Работа над ошибками: разбор всех вопросов с правильными/неправильными ответами.
// Открывается только после сдачи (finishQuiz), когда сервер уже вернул ключи.
function openReview() {
  if (!activeQuiz || !activeQuiz.result) return;
  const d = findDirection(activeQuiz.code);
  const { score, total } = activeQuiz.result;
  document.getElementById('reviewSub').textContent = `${d.code} · ${d.name} — ${score} из ${total}`;

  document.getElementById('reviewList').innerHTML = activeQuiz.pool
    .map((q, i) => reviewItemHtml(q, activeQuiz.answers[i], i, activeQuiz.code)).join('');

  document.getElementById('testPage').classList.add('hidden');
  document.getElementById('reviewPage').classList.remove('hidden');
  document.body.classList.add('test-open');
  window.scrollTo(0, 0);
}

function closeReview() {
  document.getElementById('reviewPage').classList.add('hidden');
  document.body.classList.remove('test-open');
  activeQuiz = null;
}

// Запрет копирования/выделения текста вопросов, пока открыт тест/КТ/разбор (body.test-open).
function wireAntiCopy() {
  const guard = (e) => { if (document.body.classList.contains('test-open')) e.preventDefault(); };
  ['copy', 'cut', 'contextmenu', 'selectstart'].forEach(evt => document.addEventListener(evt, guard));
  document.addEventListener('keydown', (e) => {
    if (!document.body.classList.contains('test-open')) return;
    const k = e.key.toLowerCase();
    if ((e.ctrlKey || e.metaKey) && (k === 'c' || k === 'x' || k === 'a' || k === 'u' || k === 's' || k === 'p')) e.preventDefault();
  });
}

function wireQuiz() {
  if (!document.getElementById('testPage')) return; // страница теста только на index.html
  document.getElementById('testExit').addEventListener('click', closeQuiz);
  document.getElementById('testPrev').addEventListener('click', quizPrev);
  document.getElementById('testNext').addEventListener('click', quizNext);
  document.getElementById('reviewBtn').addEventListener('click', openReview);
  document.getElementById('reviewExit').addEventListener('click', closeReview);
  document.getElementById('reviewClose').addEventListener('click', closeReview);
  document.getElementById('reviewScrollTop').addEventListener('click', () => {
    document.getElementById('reviewPage').scrollTo({ top: 0, behavior: 'smooth' });
  });
  document.getElementById('quizDashBtn').addEventListener('click', () => {
    closeQuiz();
    location.href = 'cabinet.html';
  });

  // Клавиатура: ENTER = далее, цифры 1-9 = выбор варианта, ESC = выход
  document.addEventListener('keydown', (e) => {
    const page = document.getElementById('testPage');
    if (page.classList.contains('hidden')) return;
    const onResult = !document.getElementById('testResult').classList.contains('hidden');
    if (e.key === 'Escape') { closeQuiz(); return; }
    if (onResult) return;
    if (e.key === 'Enter') { e.preventDefault(); quizNext(); return; }
    if (/^[1-9]$/.test(e.key)) {
      const btns = document.querySelectorAll('#testOptions [data-option]');
      const b = btns[Number(e.key) - 1];
      if (b) b.click();
    }
  });
}

/* ---------------------------------------------------------
   6) АВТОРИЗАЦИЯ / ЛИЧНЫЙ КАБИНЕТ
   --------------------------------------------------------- */
// Имя показывается в шапке (аватар-буква + подпись) сразу после входа. Приоритет:
// 1) ФИО, которое человек сам вписал в «Личные данные» (user.profile.fullName) —
//    это и есть настоящее имя клиента; 2) user.name с бэкенда (обычно равен логину —
//    телефон/цифры, до заполнения профиля); 3) если нигде нет ни одной буквы — общий
//    fallback «Пользователь», чтобы не показывать голый номер телефона.
function displayUserName(user) {
  const fullName = (user && user.profile && user.profile.fullName || '').trim();
  if (/\p{L}/u.test(fullName)) return fullName;
  const raw = (user && user.name || '').trim();
  return /\p{L}/u.test(raw) ? raw : 'Пользователь';
}

// Заполняет элемент-аватар (шапка или карточка профиля) — картинкой, если
// пользователь её загрузил, иначе первой буквой имени (как было раньше).
function renderAvatarInto(el, user) {
  if (!el) return;
  const avatar = user && user.profile && user.profile.avatar;
  if (avatar) {
    el.innerHTML = `<img src="${avatar}" alt="">`;
    el.classList.add('has-image');
  } else {
    el.innerHTML = '';
    el.textContent = displayUserName(user)[0].toUpperCase();
    el.classList.remove('has-image');
  }
}

function refreshAuthUI() {
  // элементы различаются на index.html и cabinet.html — всё null-safe
  const user = API.getCurrentUser();
  const chip = document.getElementById('userChip');
  const guestLogin = document.getElementById('btnGuestLogin');
  const guestRegister = document.getElementById('btnGuestRegister');
  const authZone = document.getElementById('authZone');
  const dashboard = document.getElementById('dashboard');
  const avatar = document.getElementById('userAvatar');
  const nameLabel = document.getElementById('userNameLabel');

  if (user) {
    chip?.classList.remove('hidden');
    guestLogin?.classList.add('hidden');
    guestRegister?.classList.add('hidden');
    const displayName = displayUserName(user);
    renderAvatarInto(avatar, user);
    if (nameLabel) nameLabel.textContent = displayName;
    authZone?.classList.add('hidden');
    dashboard?.classList.remove('hidden');
  } else {
    chip?.classList.add('hidden');
    guestLogin?.classList.remove('hidden');
    guestRegister?.classList.remove('hidden');
    // Токен оказался невалидным/просроченным (или его не было) — снимаем класс,
    // который до fetchMe() прятал гостевой экран, иначе он останется скрытым навсегда.
    document.documentElement.classList.remove('has-token');
    authZone?.classList.remove('hidden');
    dashboard?.classList.add('hidden');
  }
}

// Пороги прохождения полной симуляции КТ — дублирует минимально нужные числа из
// KT_TYPES (kt.js): тянуть весь kt.js в кабинет ради двух порогов не стоит (см.
// комментарий ниже про дублирование названий предметов — та же причина).
const KT_PASS_RULES = {
  nauchped: { total: 130, thresholdTotal: 75 },
  profile: { total: 40, thresholdTotal: 30 },
  profile2: { total: 70, thresholdTotal: 35 }, // два профильных предмета (M078): 30 + 20×2
};

// Человекочитаемое название блока КТ/раздела темы (lang/logic/subj1/subj2) для
// направления code. lang/logic — общие для всех направлений; subj1/subj2 — через
// реальные названия профильных предметов в GOP_SUBJECTS (p1/p2).
function progressSectionLabel(code, section) {
  if (!section) return ''; // старые результаты без сохранённого раздела (до этого поля)
  if (section === 'lang') return 'Иностранный язык';
  if (section === 'logic') return 'Тест готовности к обучению (ТГО)';
  const gopId = section === 'subj1' ? 'p1' : 'p2';
  const gopCode = (typeof CONTENT_TO_GOP !== 'undefined' && CONTENT_TO_GOP[code]) || code;
  const list = GOP_SUBJECTS[gopCode];
  const item = list && list.find(x => x.id === gopId);
  return item ? item.title : section;
}

// Считает всё нужное для карточки «Прогресс подготовки» по одному направлению:
// лучшую попытку полной симуляции КТ (разрыв до порога) и историю всех симуляций,
// последние тесты по предметам, а также разбор по темам (накоплен по всем
// попыткам — и обычным тестам, и симуляциям КТ). Темы берутся из программы
// предмета (GOP_SUBJECTS), поэтому видны и те, что ещё не решались.
const progressNorm = t => String(t || '').replace(/^(Тема\s+)?\d+\.\s*/i, '').trim().toLowerCase();

