// Ссылка на тему в библиотеке конспектов этого направления (или '' — если такой темы там нет).
// Сначала точное совпадение названия, затем соответствие из PROGRESS_CONSPECT_ALIASES,
// затем совпадение первой фразы названия (в конспекте название темы бывает длиннее).
function progressConspectHref(code, topic) {
  const lib = typeof LIBRARY_CONSPECTS !== 'undefined' && LIBRARY_CONSPECTS[code];
  if (!lib || !topic) return '';
  const first = t => t.split('.')[0].trim();
  const key = progressTopicKey(code, topic);
  // Общие предметы (ТГО, английский) — в общей библиотеке COMMON_CONSPECTS: тема прогресса → раздел и тема конспекта.
  const common = PROGRESS_COMMON_CONSPECTS[key];
  if (common) return `konspekty.html?code=${common[0]}&section=${common[1]}&topic=${common[2]}`;
  const aliasKey = progressNorm((PROGRESS_CONSPECT_ALIASES[code] || {})[topic] || '');
  const tests = [
    t => t === key,
    t => !!aliasKey && t === aliasKey,
    t => first(t).startsWith(first(key)) || first(key).startsWith(first(t)),
  ];
  for (const test of tests) {
    for (const sec of lib.sections || []) {
      const idx = (sec.topics || []).findIndex(t => test(progressNorm(t.title)));
      if (idx >= 0) return `konspekty.html?code=${encodeURIComponent(code)}&section=${encodeURIComponent(sec.key)}&topic=${idx}`;
    }
  }
  // Общий французский (раздел «Иностранный язык» у M019) живёт в общей библиотеке, не в профильной.
  if (FRENCH_LANG_CODES.has(code)) {
    const fr = COMMON_CONSPECTS.french;
    for (const sec of fr.sections) {
      const idx = sec.topics.findIndex(t => progressNorm(t.title) === key);
      if (idx >= 0) return `konspekty.html?code=french&section=${encodeURIComponent(sec.key)}&topic=${idx}`;
    }
  }
  return '';
}

// Статус темы по доле верных ответов.
function progressTopicStatus(t) {
  if (!t.n) return { key: 'none', label: 'Не решали' };
  if (t.acc >= 80) return { key: 'ok', label: 'Хорошо' };
  if (t.acc >= 50) return { key: 'mid', label: 'Средне' };
  return { key: 'low', label: 'Слабо' };
}

function computeProgressForCode(code, user) {
  const isKt = r => typeof r.kind === 'string' && r.kind.indexOf('kt:') === 0;
  const results = (user.results || []).filter(r => r.code === code);
  const ktAttempts = results.filter(isKt);
  let best = null;
  ktAttempts.forEach(r => { if (!best || r.score > best.score) best = r; });
  let kt = null;
  if (best) {
    const rule = KT_PASS_RULES[best.kind.slice(3)];
    if (rule) {
      kt = {
        score: best.score, total: best.total, date: best.date, passed: !!best.passed,
        thresholdTotal: rule.thresholdTotal,
        gap: Math.max(0, rule.thresholdTotal - best.score),
      };
    }
  }
  // История симуляций — в порядке прохождения (results хранятся хронологически).
  const ktHistory = ktAttempts.map((r, i) => {
    const rule = KT_PASS_RULES[r.kind.slice(3)];
    const prev = ktAttempts[i - 1];
    return { score: r.score, total: r.total, date: r.date, passed: !!r.passed, threshold: rule ? rule.thresholdTotal : null, delta: prev ? r.score - prev.score : null };
  });
  const subjectTests = results.filter(r => !isKt(r))
    .map(r => ({ score: r.score, total: r.total, date: r.date, pct: r.total ? Math.round((r.score / r.total) * 100) : 0, label: progressSectionLabel(code, r.section) }));

  // Темы общего французского не показываем там, где общий язык теперь английский (у M019 остались от прежних попыток).
  const frTopics = new Set(FRENCH_LANG_TOPICS.map(progressNorm));
  const stats = (user.topicStats || []).filter(t => t.code === code
    && !(t.section === 'lang' && !FRENCH_LANG_CODES.has(code) && frTopics.has(progressNorm(t.topic))));
  const gopCode = (typeof CONTENT_TO_GOP !== 'undefined' && CONTENT_TO_GOP[code]) || code;
  const gop = GOP_SUBJECTS[gopCode] || [];
  const specFor = s => {
    const id = { lang: 'lang', logic: 'tgo', subj1: 'p1', subj2: 'p2' }[s];
    const item = gop.find(x => x.id === id);
    return item ? item.topics || [] : [];
  };

  const statSections = new Set(stats.map(t => t.section));
  const sections = ['lang', 'logic', 'subj1', 'subj2'].filter(s => statSections.has(s)).map(s => {
    // Темы программы + темы из статистики, которых в программе нет (старые названия).
    const merged = new Map();
    specFor(s).forEach(title => merged.set(progressNorm(title), { topic: title, correct: 0, wrong: 0 }));
    stats.filter(t => t.section === s).forEach(t => {
      const k = progressTopicKey(code, t.topic);
      const m = merged.get(k) || { topic: (PROGRESS_TOPIC_ALIASES[code] || {})[t.topic] || t.topic, correct: 0, wrong: 0 };
      m.correct += t.correct; m.wrong += t.wrong;
      merged.set(k, m);
    });
    const topics = [...merged.values()].map(t => {
      const n = t.correct + t.wrong;
      const row = { ...t, n, acc: n ? Math.round((t.correct / n) * 100) : null, href: progressConspectHref(code, t.topic) };
      row.status = progressTopicStatus(row);
      return row;
    }).sort((a, b) => {
      if (!a.n !== !b.n) return a.n ? -1 : 1;                  // нерешённые — в конец
      if (a.n && b.n && a.acc !== b.acc) return a.acc - b.acc;  // слабые — вверху
      return b.n - a.n;
    });
    const correct = topics.reduce((x, t) => x + t.correct, 0);
    const wrong = topics.reduce((x, t) => x + t.wrong, 0);
    const n = correct + wrong;
    return {
      section: s, label: progressSectionLabel(code, s), correct, wrong, n,
      pct: n ? Math.round((correct / n) * 100) : null,
      topics, tried: topics.filter(t => t.n).length, weak: topics.filter(t => t.status.key === 'low').length,
    };
  });

  // «Что повторить»: самые слабые темы по всем разделам (точность < 70 %).
  const focus = sections.flatMap(s => s.topics.filter(t => t.n && t.acc < 70).map(t => ({ ...t, sectionLabel: s.label })))
    .sort((a, b) => a.acc - b.acc || b.n - a.n).slice(0, 3);

  return { code, kt, ktHistory, subjectTests, sections, focus };
}

// Раздел «Прогресс подготовки»: разрыв до порога КТ, история симуляций, что повторить,
// точность по разделам и все темы программы — по каждому направлению, где есть
// хоть какие-то данные (попытка КТ или разбор по темам обычного теста).
let progressActiveCode = null;
function renderProgress() {
  const user = API.getCurrentUser();
  const section = document.getElementById('progressSection');
  if (!user || !section) return;

  const codes = new Set();
  (user.results || []).forEach(r => { if (typeof r.kind === 'string' && r.kind.indexOf('kt:') === 0) codes.add(r.code); });
  (user.topicStats || []).forEach(t => codes.add(t.code));

  if (codes.size === 0) {
    section.classList.add('hidden');
    return;
  }
  section.classList.remove('hidden');

  const codeList = [...codes];
  if (!progressActiveCode || !codeList.includes(progressActiveCode)) progressActiveCode = codeList[0];

  document.getElementById('progTabs').innerHTML = codeList.map(code => {
    const d = findDirection(code);
    // Общие тесты (английский/ТГО) без выданного направления идут под служебным кодом COMMON_TEST_CODE — направлением его не называем.
    const commonOnly = code === COMMON_TEST_CODE && !(user.access || []).includes(code);
    const label = commonOnly ? 'Общие предметы · Английский и ТГО' : d ? `${d.code} · ${d.name}` : code;
    return `<button class="prog-tab ${code === progressActiveCode ? 'is-active' : ''}" data-code="${code}">${esc(label)}</button>`;
  }).join('');
  document.querySelectorAll('#progTabs .prog-tab').forEach(b => b.addEventListener('click', () => {
    if (b.dataset.code === progressActiveCode) return;
    progressActiveCode = b.dataset.code;
    renderProgress();
  }));

  const data = computeProgressForCode(progressActiveCode, user);
  const body = document.getElementById('progBody');
  const tierOf = pct => pct == null ? '' : (pct >= 80 ? '' : (pct >= 50 ? 'is-mid' : 'is-low'));
  const deltaText = d => d == null ? '' : (d > 0 ? '+' + d : (d < 0 ? '−' + Math.abs(d) : '±0'));

  let heroHtml = '';
  if (data.kt) {
    const circumference = 2 * Math.PI * 50;
    const frac = Math.max(0, Math.min(1, data.kt.score / data.kt.total));
    const gapLabel = data.kt.gap > 0
      ? `<span class="prog-stat-num danger">+${data.kt.gap} ${pluralPoints(data.kt.gap)}</span>`
      : `<span class="prog-stat-num ok">Порог пройден</span>`;
    heroHtml = `
      <div class="prog-hero">
        <div class="prog-gauge-card">
          <div class="prog-gauge-wrap">
            <svg viewBox="0 0 116 116">
              <circle class="prog-gauge-track" cx="58" cy="58" r="50"></circle>
              <circle class="prog-gauge-fill ${data.kt.passed ? 'is-pass' : ''}" cx="58" cy="58" r="50"
                stroke-dasharray="${(frac * circumference).toFixed(1)} ${circumference.toFixed(1)}"></circle>
            </svg>
            <div class="prog-gauge-center">
              <span class="prog-gauge-num">${data.kt.score}</span>
              <span class="prog-gauge-den">из ${data.kt.total}</span>
            </div>
          </div>
          <p class="prog-gauge-caption">Лучшая симуляция КТ · порог — <b>${data.kt.thresholdTotal}</b></p>
        </div>
        <div class="prog-stat-col">
          <div class="prog-stat">
            <span class="prog-stat-label">Не хватает до порога</span>
            ${gapLabel}
            <span class="prog-stat-note">по сумме — ${data.kt.score} из нужных ${data.kt.thresholdTotal}</span>
          </div>
          <div class="prog-stat">
            <span class="prog-stat-label">Итог симуляции</span>
            <span class="prog-stat-num ${data.kt.passed ? 'ok' : 'danger'}">${data.kt.passed ? I18N.t('test.passed') : I18N.t('test.notPassed')}</span>
            <span class="prog-stat-note">от ${data.kt.date}</span>
          </div>
          <div class="prog-stat">
            <span class="prog-stat-label">Попыток учтено</span>
            <span class="prog-stat-num">${data.ktHistory.length + data.subjectTests.length}</span>
            <span class="prog-stat-note">симуляций КТ — ${data.ktHistory.length}, тестов по предметам — ${data.subjectTests.length}</span>
          </div>
        </div>
      </div>`;
  } else if (data.sections.length) {
    // Есть результаты по отдельным предметам, но не было полной симуляции КТ —
    // не пересчитываем это в «разрыв до порога» (у отдельных тестов и блоков
    // симуляции разный размер пула и для части предметов разное начисление
    // баллов), просто показываем честную сводку по тому, что реально пройдено.
    const totalCorrect = data.sections.reduce((s, sec) => s + sec.correct, 0);
    const totalN = data.sections.reduce((s, sec) => s + sec.n, 0);
    const pct = totalN ? Math.round((totalCorrect / totalN) * 100) : 0;
    const note = I18N.t('progress.noKt.subjectsNote')
      .replace('{n}', data.sections.length).replace('{correct}', totalCorrect).replace('{count}', totalN).replace('{pct}', pct);
    heroHtml = `<p class="prog-empty">${I18N.t('progress.noKt.lead')}</p><p class="prog-section-note">${note}</p>`;
  } else {
    heroHtml = `<p class="prog-empty">${I18N.t('progress.noKt.empty')}</p>`;
  }

  // История симуляций КТ: балл каждой попытки, отметка порога, изменение к прошлой попытке.
  const historyHtml = data.ktHistory.length > 1 ? `
    <div class="prog-section">
      <h4>История симуляций КТ</h4>
      <p class="prog-section-note">Все попытки по порядку; вертикальная черта — порог прохождения.</p>
      ${data.ktHistory.map((h, i) => `
        <div class="prog-hist-row">
          <span class="prog-hist-no">${i + 1}</span>
          <span class="prog-hist-date">${esc(h.date || '')}</span>
          <div class="prog-hist-bar">
            <div class="prog-hist-fill ${h.passed ? 'is-pass' : ''}" style="width:${h.total ? Math.round((h.score / h.total) * 100) : 0}%"></div>
            ${h.threshold && h.total ? `<span class="prog-hist-mark" style="left:${Math.round((h.threshold / h.total) * 100)}%"></span>` : ''}
          </div>
          <span class="prog-hist-score">${h.score}/${h.total}</span>
          <span class="prog-hist-delta ${h.delta > 0 ? 'up' : (h.delta < 0 ? 'down' : '')}">${deltaText(h.delta)}</span>
        </div>`).join('')}
    </div>` : '';

  // Что повторить в первую очередь.
  const focusHtml = data.focus.length ? `
    <div class="prog-section">
      <h4>Что повторить в первую очередь</h4>
      <p class="prog-section-note">Темы с самой низкой долей верных ответов за все попытки.</p>
      <div class="prog-focus-list">
        ${data.focus.map(t => `
          <div class="prog-focus-card">
            <span class="prog-focus-sec">${esc(t.sectionLabel)}</span>
            <span class="prog-focus-name">${esc(t.topic)}</span>
            <span class="prog-focus-stat">верно ${t.correct} из ${t.n} · <b>${t.acc}%</b></span>
            ${t.href ? `<a class="prog-focus-link" href="${t.href}">Открыть конспект →</a>` : ''}
          </div>`).join('')}
      </div>
    </div>` : '';

  const blocksHtml = data.sections.length ? `
    <div class="prog-section">
      <h4>Точность по разделам</h4>
      <p class="prog-section-note">Доля верных ответов по всем вопросам раздела. Нажмите на раздел, чтобы открыть его темы.</p>
      ${data.sections.map(s => `
        <a class="prog-block-row" href="#prog-topics-${esc(s.section)}">
          <div class="prog-block-name">${esc(s.label)}
            <span class="prog-block-note">верно ${s.correct} из ${s.n} · тем решали ${s.tried} из ${s.topics.length}${s.weak ? ` · слабых ${s.weak}` : ''}</span>
          </div>
          <div class="prog-block-bar"><div class="prog-block-fill ${tierOf(s.pct)}" style="width:${s.pct ?? 0}%"></div></div>
          <div class="prog-block-pct">${s.pct == null ? '—' : s.pct + '%'}</div>
        </a>`).join('')}
    </div>` : '';

  // Все темы раздела (включая нерешённые) — свёрнуты по умолчанию.
  const topicsHtml = data.sections.map(s => {
    const untouched = s.topics.length - s.tried;
    const summaryNote = [
      s.weak ? `слабых ${s.weak}` : (s.tried ? 'слабых тем нет' : ''),
      untouched ? `не решали ${untouched}` : '',
    ].filter(Boolean).join(' · ');
    return `
    <details class="prog-section prog-topics-details" id="prog-topics-${esc(s.section)}">
      <summary class="prog-topics-summary">
        <span class="prog-topics-summary-title">Темы · ${esc(s.label)}</span>
        <span class="prog-topics-summary-note">${summaryNote}</span>
      </summary>
      <p class="prog-section-note">Доля верных ответов по теме за все попытки: сначала слабые, в конце — темы, которые ещё не попадались.</p>
      ${s.topics.map(t => `
        <div class="prog-topic-row${t.n ? '' : ' is-untried'}">
          <div class="prog-topic-main">
            <span class="prog-topic-name">${esc(t.topic)}</span>
            <span class="prog-topic-meta">
              <span class="prog-chip is-${t.status.key}">${t.status.label}</span>
              ${t.n ? `<span>верно ${t.correct} из ${t.n}${t.n < 3 ? ' · мало ответов' : ''}</span>` : ''}
              ${t.href ? `<a class="prog-topic-link" href="${t.href}">конспект</a>` : ''}
            </span>
          </div>
          <div class="prog-topic-bar"><div class="prog-topic-fill is-${t.status.key}" style="width:${t.acc ?? 0}%"></div></div>
          <div class="prog-topic-pct is-${t.status.key}">${t.acc == null ? '—' : t.acc + '%'}</div>
        </div>`).join('')}
    </details>`;
  }).join('');

  // Последние тесты по предметам.
  const recent = data.subjectTests.slice(-5).reverse();
  const testsHtml = recent.length ? `
    <div class="prog-section">
      <h4>Последние тесты по предметам</h4>
      <p class="prog-section-note">Пять последних попыток, сверху — самая свежая.</p>
      ${recent.map(r => `
        <div class="prog-hist-row${r.label ? ' has-label' : ''}">
          ${r.label
            ? `<div class="prog-hist-label-date"><span class="prog-hist-label">${esc(r.label)}</span><span class="prog-hist-date">${esc(r.date || '')}</span></div>`
            : `<span class="prog-hist-date">${esc(r.date || '')}</span>`}
          <div class="prog-hist-bar"><div class="prog-hist-fill ${r.pct >= 50 ? 'is-pass' : ''}" style="width:${r.pct}%"></div></div>
          <span class="prog-hist-score">${r.score}/${r.total}</span>
          <span class="prog-hist-delta">${r.pct}%</span>
        </div>`).join('')}
    </div>` : '';

  // Полный разбор по темам + история — самая длинная часть блока (на телефоне
  // это лишний экран прокрутки до «Что повторить»/гейджа при каждом заходе),
  // сворачиваем под один тумблер; «Точность по разделам» остаётся видной сразу —
  // это уже компактная сводка на 3-4 строки.
  const moreHtml = (historyHtml || topicsHtml || testsHtml) ? `
    <details class="prog-section prog-more">
      <summary class="prog-more-summary">Подробная статистика</summary>
      ${historyHtml}${topicsHtml}${testsHtml}
    </details>` : '';

  body.innerHTML = heroHtml + focusHtml + blocksHtml + moreHtml
    || `<p class="prog-empty">Пока недостаточно данных для разбора по темам.</p>`;

  // Клик по строке раздела выше должен не просто проскроллить, а ещё и
  // раскрыть свёрнутый блок тем — на случай браузеров без auto-expand
  // свёрнутых <details> при переходе по #якорю, и раскрыть внешний тумблер
  // «Подробная статистика», внутри которого теперь лежит блок тем.
  document.querySelectorAll('.prog-block-row').forEach(a => a.addEventListener('click', () => {
    const el = document.querySelector(a.getAttribute('href'));
    if (el && 'open' in el) el.open = true;
    const wrap = el && el.closest('details.prog-more');
    if (wrap) wrap.open = true;
  }));
}

function pluralPoints(n) {
  const n10 = n % 10, n100 = n % 100;
  if (n10 === 1 && n100 !== 11) return 'балл';
  if ([2, 3, 4].includes(n10) && ![12, 13, 14].includes(n100)) return 'балла';
  return 'баллов';
}

function renderDashboard() {
  const user = API.getCurrentUser();
  if (!user || !document.getElementById('dashboard')) return; // дашборд только на cabinet.html

  // «Пройти тест»: по карточке на каждое направление с выданным доступом — ведёт
  // прямо в ту же модалку (предметы + «Пройти тест»/«Симуляция КТ»), что открывается
  // из каталога на главной, без похода туда вручную. Если доступа ещё нет — как
  // раньше, одна карточка-приглашение в общий каталог.
  renderTestAccessCards();
  renderConspectsLibrary();
  renderProgress();

  // --- Личные данные: просмотр или редактирование ---
  const p = user.profile;
  fillProfileForm(user);
  renderProfileView(user);
  // пустой профиль → сразу форма (без «Отмены»); есть данные → просмотр
  setProfileMode(profileIsEmpty(p) ? 'first' : 'view');

  loadRoadmap();

  // --- Результаты тестов ---
  const summary = document.getElementById('resultSummary');
  const table = document.getElementById('resultsTable');
  const body = document.getElementById('resultsBody');
  const empty = document.getElementById('dashResultsEmpty');
  const rows = [...user.results].reverse();

  if (rows.length > 0) {
    const last = rows[0];
    const pct = Math.round((last.score / last.total) * 100);
    const passed = pct >= 60;
    const d = findDirection(last.code);
    summary.innerHTML = `
      <span class="rs-label">Текущий результат</span>
      <span class="rs-value">${last.score} / ${last.total} · ${pct}%</span>
      <span class="test-status-badge ${passed ? 'passed' : 'failed'}">${passed ? 'Сдан' : 'Не сдан'}</span>
      <span class="rs-dir">${d ? d.code + ' · ' + d.name : last.code}</span>
    `;
    summary.classList.remove('hidden');
  } else {
    summary.classList.add('hidden');
  }

  body.innerHTML = rows.map((r, i) => {
    const pct = Math.round((r.score / r.total) * 100);
    const passed = pct >= 60;
    const d = findDirection(r.code);
    const q = new URLSearchParams({ result: r.code, score: r.score, total: r.total, date: r.date });
    if (r.attemptId) q.set('attempt', r.attemptId); // разбор ответов этой попытки
    return `
      <tr class="results-row" data-href="index.html?${q.toString()}" tabindex="0">
        <td class="results-num">${i + 1}</td>
        <td>${d ? `${d.code} · ${d.name}` : r.code}</td>
        <td>${r.score}/${r.total}</td>
        <td><span class="test-status-badge ${passed ? 'passed' : 'failed'}">${passed ? 'Сдан' : 'Не сдан'}</span></td>
        <td>${r.date}</td>
      </tr>
    `;
  }).join('');
  body.querySelectorAll('.results-row').forEach(tr => {
    const go = () => location.href = tr.dataset.href;
    tr.addEventListener('click', go);
    tr.addEventListener('keydown', (e) => { if (e.key === 'Enter') go(); });
  });
  empty.classList.toggle('hidden', rows.length > 0);
  table.classList.toggle('hidden', rows.length === 0);
}

// Человекочитаемые названия профильных предметов по коду направления и ключу
// секции (subj1/subj2 — как в bySubject контента с бэкенда). Небольшое
// намеренное дублирование KT_SUBJECT_NAMES из kt.js: kt.js не подключён на
// cabinet.html (там только вопросы для симуляции КТ на index.html), тянуть
// его целиком сюда ради одной подписи — лишний вес страницы.

/* --- Личные данные: режимы просмотра / редактирования --- */
function profileIsEmpty(p) {
  return !(p.fullName || p.phone || p.education || p.city || p.specialityId);
}

function fillProfileForm(user) {
  const p = user.profile;
  renderAvatarInto(document.getElementById('pfAvatarPreview'), user);
  document.getElementById('pfAvatarRemoveBtn')?.classList.toggle('hidden', !p.avatar);
  document.getElementById('pfFullName').value = p.fullName || '';
  document.getElementById('pfEmail').value = user.email || '';
  document.getElementById('pfPhone').value = p.phone || '';
}

function renderProfileView(user) {
  const view = document.getElementById('profileView');
  if (!view) return;
  const p = user.profile;
  const dash = '—';
  const rows = [
    ['ФИО', p.fullName], ['Email', user.email], ['Телефон', p.phone],
  ];
  view.innerHTML = rows.map(([k, v]) => `
    <div class="pv-row"><span class="pv-key">${k}</span><span class="pv-val">${v ? esc(String(v)) : dash}</span></div>
  `).join('');
}

// mode: 'view' | 'edit' | 'first' (первое заполнение — форма без «Отмены»)
function setProfileMode(mode) {
  const view = document.getElementById('profileView');
  const form = document.getElementById('profileForm');
  const editBtn = document.getElementById('pfEditBtn');
  const cancelBtn = document.getElementById('pfCancelBtn');
  if (!view || !form) return;
  const editing = mode !== 'view';
  view.classList.toggle('hidden', editing);
  form.classList.toggle('hidden', !editing);
  editBtn?.classList.toggle('hidden', editing);
  cancelBtn?.classList.toggle('hidden', mode !== 'edit');
}

