const AVATAR_SIZE = 256; // сторона квадрата, до которого уменьшаем фото перед загрузкой

// Уменьшает выбранный файл-картинку до AVATAR_SIZE×AVATAR_SIZE (обрезка по центру
// до квадрата, как обычно делают аватары), сжимает в JPEG — чтобы не хранить на
// сервере огромные фото прямо с телефона (там легко 5-10 МБ за кадр).
function cropAndEncodeAvatar(file) {
  return new Promise((resolve, reject) => {
    const img = new Image();
    const url = URL.createObjectURL(file);
    img.onload = () => {
      URL.revokeObjectURL(url);
      const side = Math.min(img.naturalWidth, img.naturalHeight);
      const sx = (img.naturalWidth - side) / 2;
      const sy = (img.naturalHeight - side) / 2;
      const canvas = document.createElement('canvas');
      canvas.width = AVATAR_SIZE;
      canvas.height = AVATAR_SIZE;
      const ctx = canvas.getContext('2d');
      ctx.drawImage(img, sx, sy, side, side, 0, 0, AVATAR_SIZE, AVATAR_SIZE);
      resolve(canvas.toDataURL('image/jpeg', 0.85));
    };
    img.onerror = () => { URL.revokeObjectURL(url); reject(new Error('Не удалось прочитать изображение')); };
    img.src = url;
  });
}

function wireAvatarUpload() {
  const input = document.getElementById('pfAvatarInput');
  const removeBtn = document.getElementById('pfAvatarRemoveBtn');
  const preview = document.getElementById('pfAvatarPreview');
  if (!input) return;

  const syncRemoveBtn = () => {
    const u = API.getCurrentUser();
    removeBtn?.classList.toggle('hidden', !(u && u.profile && u.profile.avatar));
  };
  syncRemoveBtn();

  input.addEventListener('change', async () => {
    const file = input.files && input.files[0];
    input.value = ''; // чтобы повторный выбор того же файла тоже сработал
    if (!file) return;
    if (!file.type.startsWith('image/')) { showToast('Нужен файл изображения'); return; }
    try {
      const dataUrl = await cropAndEncodeAvatar(file);
      await API.setAvatar(dataUrl);
      refreshAuthUI();
      renderAvatarInto(preview, API.getCurrentUser());
      syncRemoveBtn();
      showToast('Фото профиля обновлено');
    } catch (err) {
      showToast(err.message || 'Не удалось загрузить фото');
    }
  });

  removeBtn?.addEventListener('click', async () => {
    try {
      await API.setAvatar('');
      refreshAuthUI();
      renderAvatarInto(preview, API.getCurrentUser());
      syncRemoveBtn();
      showToast('Фото профиля удалено');
    } catch (err) {
      showToast(err.message || 'Не удалось удалить фото');
    }
  });
}

function wireProfileForm() {
  const form = document.getElementById('profileForm');
  if (!form) return;
  form.addEventListener('submit', async (e) => {
    e.preventDefault();
    const btn = form.querySelector('button[type="submit"]');
    setBtnLoading(btn, true, 'Сохранение…');
    try {
      // Образование/город/специальность/язык/цель/баллы КТ убраны из формы —
      // но бэкенд сохраняет профиль целиком, поэтому шлём их значения как были
      // (из уже загруженного user.profile), чтобы не затереть то, что там уже
      // могло быть сохранено раньше.
      const p = (API.getCurrentUser() || {}).profile || {};
      await API.updateProfile({
        fullName: document.getElementById('pfFullName').value.trim(),
        phone: document.getElementById('pfPhone').value.trim(),
        education: p.education || '',
        city: p.city || '',
        specialityId: p.specialityId || 0,
        language: p.language || '',
        targetType: p.targetType || '',
        foreignScore: p.foreignScore || 0,
        profileScore: p.profileScore || 0,
        bonusPoints: p.bonusPoints || 0,
      });
      const saved = document.getElementById('profileSaved');
      saved.classList.remove('hidden');
      clearTimeout(form._savedTimer);
      form._savedTimer = setTimeout(() => saved.classList.add('hidden'), 2000);
      refreshAuthUI();   // обновить имя в шапке
      const u = API.getCurrentUser();
      renderProfileView(u);
      setProfileMode('view'); // после сохранения — режим просмотра
      showToast('Личные данные сохранены');
    } catch (err) {
      showToast(err.message);
    } finally {
      setBtnLoading(btn, false);
    }
  });
}

/* Индикатор загрузки на кнопке (для медленного холодного старта сервера) */
function setBtnLoading(btn, loading, label) {
  if (!btn) return;
  if (loading) {
    btn.dataset.orig = btn.textContent;
    btn.textContent = label || 'Подождите…';
    btn.disabled = true;
  } else {
    if (btn.dataset.orig) btn.textContent = btn.dataset.orig;
    btn.disabled = false;
  }
}

function openAuth() {
  // кабинет живёт на отдельной странице; с других страниц — переход
  const zone = document.getElementById('authZone');
  if (!zone) { location.href = 'cabinet.html'; return; }
  document.getElementById('account').scrollIntoView({ behavior: 'smooth' });
}

function wireAuth() {
  document.querySelectorAll('[data-open-auth]').forEach(el => {
    el.addEventListener('click', (e) => { e.preventDefault(); openAuth(); });
  });
  const loginForm = document.getElementById('loginForm');
  if (loginForm) loginForm.addEventListener('submit', async (e) => {
    e.preventDefault();
    const email = document.getElementById('loginEmail').value.trim();
    const password = document.getElementById('loginPassword').value;
    const errorEl = document.getElementById('loginError');
    const btn = e.target.querySelector('button[type="submit"]');
    errorEl.textContent = '';
    setBtnLoading(btn, true, 'Вход…');
    try {
      await API.login(email, password);
      showToast('Добро пожаловать!');
      afterAuthChange();
    } catch (err) {
      errorEl.textContent = err.message;
    } finally {
      setBtnLoading(btn, false);
    }
  });

  const btnLogout = document.getElementById('btnLogout');
  if (btnLogout) btnLogout.addEventListener('click', () => {
    API.logout();
    showToast('Вы вышли из аккаунта');
    afterAuthChange();
  });
}

function afterAuthChange() {
  refreshAuthUI();
  renderDashboard();
  renderCatalog();
}

/* ---------------------------------------------------------
   TOAST
   --------------------------------------------------------- */
let toastTimeout = null;
function showToast(message, duration = 2200) {
  const overlay = document.getElementById('toastOverlay');
  const toast = document.getElementById('toast');
  toast.textContent = message;
  overlay.classList.remove('hidden');
  overlay.style.background = 'transparent';
  overlay.style.alignItems = 'flex-start';
  overlay.style.justifyContent = 'center';
  overlay.style.paddingTop = '24px';
  overlay.style.pointerEvents = 'none';
  clearTimeout(toastTimeout);
  toastTimeout = setTimeout(() => overlay.classList.add('hidden'), duration);
}

// «С возвращением»: если последний тест был не сегодня — напоминаем результат
// при следующем заходе на сайт (один раз на результат, дальше не повторяем).
function checkWelcomeBackMessage() {
  const user = API.getCurrentUser();
  if (!user || !Array.isArray(user.results) || !user.results.length) return;
  const last = user.results[user.results.length - 1];
  const todayStr = new Date().toISOString().slice(0, 10); // YYYY-MM-DD — тот же формат, что и в дате результата
  if (last.date === todayStr) return; // тест сдавали сегодня — рано напоминать

  const seenKey = 'jetishub-welcomeback-seen';
  const seenValue = `${last.date}|${last.code}|${last.score}|${last.total}`;
  if (localStorage.getItem(seenKey) === seenValue) return; // это уже показывали
  localStorage.setItem(seenKey, seenValue);

  const pct = Math.round((last.score / last.total) * 100);
  const passed = pct >= 60;
  const d = findDirection(last.code);
  const dirName = d ? d.name : last.code;
  const msg = passed
    ? `🎉 С возвращением! В прошлый раз вы хорошо прошли тест по направлению «${dirName}» — ${last.score} из ${last.total} (${pct}%). Так держать!`
    : `С возвращением! Результат прошлого теста по направлению «${dirName}» — ${last.score} из ${last.total} (${pct}%), порог пока не взят. Не останавливайтесь — ещё одна попытка, и всё получится!`;
  showToast(msg, 6000);
}

