function renderRoadmap(data) {
  document.getElementById('rmYear').textContent = data.year;
  document.getElementById('rmProgressRing').innerHTML = ringSvg(data.progress, { size: 56, stroke: 5, color: 'var(--accent)', numFontSize: 12 });
  document.getElementById('rmEmpty').classList.add('hidden');

  const isKk = I18N.getLang() === 'kk';
  const fmt = (d) => { const [y, m, day] = d.split('-'); return isKk ? `${Number(day)}.${m}.${y} дейін` : `до ${Number(day)}.${m}.${y}`; };
  document.getElementById('rmList').innerHTML = data.steps.map(s => `
    <li class="rm-step ${s.completed ? 'is-done' : ''}">
      <button class="rm-check" data-rm="${s.template_id}" aria-label="${I18N.t('roadmap.check.aria')}">${s.completed ? '✓' : ''}</button>
      <span class="rm-text">${esc(s.description)}</span>
      <span class="rm-deadline">${fmt(s.deadline)}</span>
    </li>
  `).join('');

  document.querySelectorAll('[data-rm]').forEach(btn => {
    btn.addEventListener('click', async () => {
      try {
        renderRoadmap(await apiFetch(`/api/roadmap/toggle?lang=${I18N.getLang()}`, {
          method: 'POST', auth: true, body: { template_id: Number(btn.dataset.rm) },
        }));
      } catch (e) { showToast(e.message); }
    });
  });
}

/* ---------------------------------------------------------
   INIT
   --------------------------------------------------------- */
document.addEventListener('DOMContentLoaded', async () => {
  // Каталог направлений (10 карточек) и каталог из 147 ГОП-групп — самая
  // тяжёлая синхронная работа на старте (сборка innerHTML + layout для 147
  // карточек с SVG-кольцами). На главной это перекрывало отрисовку уже
  // загруженной hero-картинки почти на 2с (Lighthouse: LCP render delay) —
  // сдвигаем на кадр позже, чтобы браузер успел показать то, что уже готово,
  // до этой синхронной сборки.
  // Чистый requestAnimationFrame тут не годится: в фоновой/неактивной вкладке
  // (открыли в новой вкладке не переключаясь, или ушли с сайта до конца
  // загрузки) rAF браузером не вызывается вообще — каталог не рисовался
  // никогда, а не просто с задержкой. setTimeout-фолбэк гарантирует отрисовку
  // максимум через 100мс, даже если вкладка не активна.
  (function renderCatalogsSoon() {
    let done = false;
    const run = () => {
      if (done) return;
      done = true;
      renderCatalog();
      renderStatsCatalog();
    };
    requestAnimationFrame(run);
    setTimeout(run, 100);
  })();
  // Переключение RU/KK не перезагружает страницу — динамические блоки, которые
  // сами вызывают I18N.t(), нужно перерисовать вручную, иначе метки останутся
  // на прежнем языке до следующей перезагрузки.
  document.addEventListener('jetishub-lang-change', () => {
    renderStatsCatalog();
    if (lastOpenGopCode && document.getElementById('dirModal') && !document.getElementById('dirModal').classList.contains('hidden')) {
      renderGopModalView(lastOpenGopCode);
    }
    loadRoadmap();
  });
  // Если токен уже есть в localStorage, пользователь почти наверняка залогинен —
  // скрываем гостевой экран («Войдите, чтобы продолжить») сразу, не дожидаясь
  // fetchMe(), иначе на долю секунды мелькает неверное состояние. Дашборд по
  // умолчанию и так скрыт разметкой (class="hidden"), покажем его позже.
  if (getToken()) document.getElementById('authZone')?.classList.add('hidden');
  else refreshAuthUI();
  wireAuth();
  wireProfileForm();
  wireProfileModes();
  wireAvatarUpload();
  wireSearch();
  wireDirModal();
  wireGate();
  wireSubjectModal();
  wireQuiz();
  wireAntiCopy();
  wireMobileNav();
  initScrollReveal();
  initPathTimeline();
  initHeaderContrast();
  document.getElementById('pathPrepBtn')?.addEventListener('click', () => {
    document.getElementById('catalog').scrollIntoView({ behavior: 'smooth' });
  });

  // справочники нужны ДО renderDashboard (иначе селекты пустые и value не встанет)
  await loadRefs();

  // подтягиваем пользователя по сохранённому токену (может быть медленно
  // на «холодном» сервере) и перерисовываем зависимые от него части
  await API.fetchMe();
  refreshAuthUI();
  renderDashboard();
  renderCatalog(); // чтобы подсветить избранное на карточках
  checkWelcomeBackMessage();

  // автозапуск теста по ссылке из кабинета: index.html?test=7M06
  const testCode = new URLSearchParams(location.search).get('test');
  const testCodeDir = testCode ? findDirection(testCode) : null;
  if (testCode && document.getElementById('testPage') && requireAuth(testCodeDir && testCodeDir.code, testCodeDir && testCodeDir.name)) {
    if (INTERACTIVE_TEST_CODES.includes(testCode)) startQuiz(testCode);
    else showToast('Тест для этого направления временно недоступен');
  }

  // автозапуск симуляции КТ по ссылке (например, со страницы статистики): index.html?kt=7M01
  const ktCode = new URLSearchParams(location.search).get('kt');
  const ktCodeDir = ktCode ? findDirection(ktCode) : null;
  if (ktCode && document.getElementById('ktPage') && requireAuth(ktCodeDir && ktCodeDir.code, ktCodeDir && ktCodeDir.name)) {
    if (INTERACTIVE_TEST_CODES.includes(ktCode)) openKTSafe(ktCode);
    else showToast('Симуляция КТ для этого направления временно недоступна');
  }

  // страница деталей пройденного теста: index.html?result=7M06&score=3&total=4&date=2026-07-05&attempt=<id>
  const qs = new URLSearchParams(location.search);
  const resultCode = qs.get('result');
  if (resultCode && document.getElementById('resultPage')) {
    const rDir = findDirection(resultCode);
    if (requireAuth(rDir && rDir.code, rDir && rDir.name)) {
      openResultDetail(resultCode, Number(qs.get('score')), Number(qs.get('total')), qs.get('date') || '', qs.get('attempt') || '');
    }
  }

  // открыть модалку направления сразу по ссылке из кабинета: index.html?openDir=7M01
  const openDirCode = qs.get('openDir');
  if (openDirCode && document.getElementById('dirModal') && findDirection(openDirCode)) {
    openDirection(openDirCode);
  }

  // то же самое, но для карточки ГОП (147 групп, напр. M123): index.html?openGop=M123
  const openGopCode = qs.get('openGop');
  if (qs.get('variant') === 'M019' || qs.get('variant') === 'M019E') gopM019Variant = qs.get('variant');
  if (openGopCode && document.getElementById('dirModal') && KT_STATS_GROUPS.find(g => g.code === openGopCode)) {
    openGopGroup(openGopCode);
  }

  // общий тест по предмету из кабинета: index.html?commonTest=lang|logic (английский / ТГО)
  if (qs.get('commonPick') && document.getElementById('subjectModal') && requireAuth()) showSubjectPicker(COMMON_TEST_CODE, true);
  const commonTest = qs.get('commonTest');
  if ((commonTest === 'lang' || commonTest === 'logic') && document.getElementById('testPage') && requireAuth()) {
    beginQuizSection(COMMON_TEST_CODE, commonTest);
  }
});

/* Страница деталей пройденного теста. Разбор берётся из СОХРАНЁННОЙ попытки
   (вопросы, ответы пользователя, ключи) — так показывается ровно то, что человек проходил,
   и нельзя открыть ответы теста, не сдав его. Разбор хранится 90 дней; у старых результатов
   (сохранённых без попытки) показывается только итог. */
async function openResultDetail(code, score, total, date, attemptId) {
  const d = findDirection(code);
  if (!d) { showToast('Направление не найдено'); return; }
  const passed = total > 0 && Math.round((score / total) * 100) >= 60;

  document.getElementById('resultStamp').classList.toggle('is-fail', !passed);
  document.getElementById('resultStampStatus').textContent = passed ? I18N.t('test.passed') : I18N.t('test.notPassed');
  document.getElementById('resultStampScore').textContent = `${score}/${total}`;
  document.getElementById('resultTitle').textContent = `${d.code} · ${d.name}`;
  document.getElementById('resultSub').textContent = date ? `Пройден ${date}` : '';

  const list = document.getElementById('resultQList');
  list.innerHTML = '';
  let rv = null;
  if (attemptId) {
    try { rv = await API.getAttemptReview(attemptId); } catch (_) { rv = null; }
  }
  if (rv) {
    // quizText() берёт настройки дробей из activeQuiz — здесь его нет, поэтому дроби не рисуем
    list.innerHTML = rv.questions
      .map((q, i) => reviewItemHtml({ ...q, ...rv.review[i] }, rv.answers[i], i, code)).join('');
  } else {
    list.innerHTML = `<p class="rev-unavailable">${esc(I18N.t('test.reviewUnavailable'))}</p>`;
  }

  document.getElementById('resultExit').onclick = () => location.href = 'cabinet.html';
  document.getElementById('resultCloseBtn').onclick = () => location.href = 'cabinet.html';
  document.getElementById('resultRetryBtn').onclick = () => startQuiz(code);

  document.getElementById('resultPage').classList.remove('hidden');
  document.body.classList.add('test-open');
  window.scrollTo(0, 0);
}
